### JavaScript (Vanilla JS with WebSocket)
```javascript
// stage.js
document.addEventListener('DOMContentLoaded', () => {
    const socket = io();
    const transcriptionBox = document.getElementById('transcriptionBox');
    const sentimentGauge = document.getElementById('sentimentGauge');
    const viewerCount = document.getElementById('viewerCount');
    const watchSourceBtn = document.getElementById('watchSource');

    // Transcription updates
    socket.on('transcription_update', (data) => {
        transcriptionBox.innerHTML += `<p>${data.text} (${data.timestamp})</p>`;
        transcriptionBox.scrollTop = transcriptionBox.scrollHeight;
    });

    // Sentiment heartbeat updates
    socket.on('sentiment_update', (data) => {
        const score = data.score * 100; // Convert to percentage
        sentimentGauge.style.background = `linear-gradient(to right, red ${score}%, yellow ${score + 20}%, green 100%)`;
    });

    // Viewer count updates
    socket.on('viewer_update', (data) => {
        viewerCount.textContent = data.count;
    });

    // Simulate partner mention detection
    socket.on('partner_mention', (data) => {
        if (data.mentioned) {
            watchSourceBtn.classList.add('active');
        } else {
            watchSourceBtn.classList.remove('active');
        }
    });
});
```

