@app.route('/api/signals', methods=['GET'])
def get_signals():
    conn = sqlite3.connect('protocol_pulse.db')
    signals = conn.execute('SELECT * FROM nostr_signals ORDER BY created_at DESC LIMIT 50').fetchall()
    conn.close()
    return jsonify(signals)

# WebSocket for real-time signal updates
