### JavaScript (Vanilla JS with WebSocket)
```javascript
// nostr_signal.js
document.addEventListener('DOMContentLoaded', () => {
    const socket = io();
    const signalFeed = document.getElementById('signalFeed');

    // Fetch initial signals
    fetch('/api/signals')
        .then(response => response.json())
        .then(signals => renderSignals(signals));

    // Real-time signal updates
    socket.on('signal_update', (data) => {
        renderSignal(data);
    });

    function renderSignals(signals) {
        signalFeed.innerHTML = '';
        signals.forEach(signal => renderSignal(signal));
    }

    function renderSignal(signal) {
        const row = document.createElement('div');
        row.className = `signal-row ${signal.urgency}`;
        row.innerHTML = `
            <span>${new Date().toLocaleTimeString()}</span>
            <span>${signal.author}: ${signal.content.slice(0, 50)}...</span>
            <span>${(signal.confidence * 100).toFixed(2)}%</span>
            <span>${signal.urgency.toUpperCase()}</span>
        `;
        signalFeed.insertBefore(row, signalFeed.firstChild);
    }
});
```

